<div class="top"><h1>Statuts de commande</h1></div>
<div class="card"><p class="muted">Adaptez les libellés, l'ordre et les e-mails automatiques. Les statuts « système » ne peuvent pas être supprimés (désactivez-les si vous ne les utilisez pas). <b>En attente de paiement, Paiement confirmé, Livré et Annulé</b> sont indispensables au fonctionnement et restent toujours actifs.</p>
<form method="post" action="/admin/statuts"><?= csrf_field() ?><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Ordre</th><th>Libellé affiché</th><th>Couleur</th><th>Actif</th><th>E-mail client</th><th>Commandes</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $r): $k = e($r['skey']); ?><tr><td><input type="number" min="0" max="999" name="st[<?= $k ?>][sort]" value="<?= (int) $r['sort'] ?>" style="width:70px"></td><td><input name="st[<?= $k ?>][label]" value="<?= e($r['label']) ?>" maxlength="80" required><br><small class="muted"><?= $k ?><?= $r['is_system'] ? ' · système' : ' · personnalisé' ?></small></td>
<td><select name="st[<?= $k ?>][tone]"><?= select_opts(['info' => 'Bleu', 'ok' => 'Vert', 'warn' => 'Orange', 'bad' => 'Rouge'], $r['tone']) ?></select></td><td><input type="checkbox" name="st[<?= $k ?>][active]" value="1" <?= $r['active'] ? 'checked' : '' ?>></td><td><input type="checkbox" name="st[<?= $k ?>][notify]" value="1" <?= $r['notify'] ? 'checked' : '' ?>></td><td><?= (int) $r['n'] ?></td>
<td><?php if (!$r['is_system'] && !$r['n']): ?><button class="btn btn-d btn-sm" type="submit" formaction="/admin/statuts/<?= $k ?>/supprimer" formnovalidate>Supprimer</button><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<h3 style="margin-top:18px">Ajouter un statut</h3><div class="row3"><div class="field"><label for="nl">Libellé</label><input id="nl" name="new_label" maxlength="80" placeholder="Ex. : En contrôle qualité"></div><div class="field"><label for="ns">Ordre</label><input id="ns" type="number" name="new_sort" value="65" min="0" max="999"></div><div class="field"><label for="nt">Couleur</label><select id="nt" name="new_tone"><?= select_opts(['info' => 'Bleu', 'ok' => 'Vert', 'warn' => 'Orange', 'bad' => 'Rouge'], 'info') ?></select></div></div>
<label class="chk"><input type="checkbox" name="new_notify" value="1"><span>Prévenir le client par e-mail lors de ce statut</span></label><div class="mt"><button class="btn btn-p" type="submit">Enregistrer</button></div></form></div>
